sql.where:
AND generation_type = 'NORMAL' AND ( 1 = 0
OR (source_type = 'FAMILY' AND creator_user_id = #{query.currentUserId}
AND EXISTS (SELECT 1 FROM learn_task_target selected_target JOIN edu_student selected_student ON selected_target.target_type='STUDENT' AND selected_target.target_id=selected_student.id JOIN sys_user_organization selected_member ON selected_member.user_id=selected_student.student_user_id WHERE selected_target.task_id=learn_task.id AND selected_member.organization_id=#{selectedOrganizationId}) )
OR (source_type = 'TEACHER' AND creator_user_id = #{query.currentUserId}) OR (source_type = 'ORGANIZATION' AND status = 'PUBLISHED' AND EXISTS ( SELECT 1 FROM learn_task_assignment visible_assignment JOIN edu_student_organization visible_student_class ON visible_student_class.student_id = visible_assignment.student_id AND visible_student_class.relation_type = 'CLASS' AND visible_student_class.status = 'ACTIVE' JOIN edu_teacher_class visible_teacher_class ON visible_teacher_class.class_organization_id = visible_student_class.organization_id AND visible_teacher_class.status = 'ACTIVE' WHERE visible_assignment.task_id = learn_task.id AND visible_teacher_class.teacher_user_id = #{query.currentUserId} ))
OR (source_type = 'ORGANIZATION' AND EXISTS ( SELECT 1 FROM sys_organization task_source_organization WHERE task_source_organization.id = learn_task.source_organization_id AND (
1 = 1 1 = 0 OR task_source_organization.organization_path LIKE CONCAT(#{path}, '%')
) ))
)
AND source_type = #{query.sourceType}
AND status = #{query.status}
AND scheduled_date = #{query.scheduledDate}
AND title LIKE CONCAT('%', #{query.keyword}, '%')

mapper.select:
SELECT  FROM learn_task

ORDER BY scheduled_date DESC, created_at DESC, id DESC
LIMIT #{query.limit} OFFSET #{query.offset}

SELECT learn_task.id, learn_task.title, learn_task.task_type, learn_task.scheduled_date, learn_task.end_date, learn_task.visibility, learn_task.status, learn_task.recurrence_enabled, learn_task.recurrence_frequency,
FROM learn_task
ORDER BY scheduled_date DESC, created_at DESC, id DESC LIMIT #{query.limit} OFFSET #{query.offset}
